    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    boolean[] visited = new boolean[n];
    visited[0] = true;
    int time = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.getNeighbors(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
                time++;
            }
        }
    }

    // Check if all apples have been collected
    for (boolean hasApple : hasApple) {
        if (!hasApple) {
            return -1;
        }
    }

    return time;
}

